CREATE OR REPLACE VIEW foo_summary AS
 SELECT id
   FROM foo_base;

CREATE AGGREGATE sum_foo_summary(foo_summary) (
    SFUNC = foo_summary_step,
    STYPE = bigint,
    INITCOND = '0'
);

CREATE OR REPLACE VIEW foo_total AS
 SELECT sum_foo_summary(foo_summary.*) AS total
   FROM foo_summary;
